import { act, fireEvent, render, screen, waitFor } from "@testing-library/react";
import { beforeEach, expect, it, vi } from "vitest";

const bridge = vi.hoisted(() => ({
  callServerTool: vi.fn(),
  listeners: new Map<string, Set<(params: unknown) => void>>(),
}));
vi.mock("@modelcontextprotocol/ext-apps", () => ({
  App: class {
    addEventListener(name: string, handler: (params: unknown) => void) {
      const handlers = bridge.listeners.get(name) ?? new Set(); handlers.add(handler); bridge.listeners.set(name, handlers);
    }
    removeEventListener() {}
    callServerTool = bridge.callServerTool;
    async connect() {}
    getHostContext() { return { theme: "light" }; }
  },
  PostMessageTransport: class { async close() {} },
}));

beforeEach(() => { bridge.listeners.clear(); bridge.callServerTool.mockReset(); });

it("does not carry edited view state across compatibility-only results", async () => {
  const parent = Object.assign(new EventTarget(), { location: { origin: "https://chatgpt.com" } });
  Object.defineProperty(window, "parent", { configurable: true, value: parent });
  bridge.callServerTool.mockImplementation(async ({ name, arguments: args }) => {
    if (name === "restore_lobu_app_result") {
      const first = args.snapshot_capability === "first-cap";
      return { isError: false, structuredContent: { found: true, tool_name: "query_sdk", data: { title: first ? "First" : "Second" }, view_state: { page: first ? 1 : 2 } } };
    }
    return { isError: false, structuredContent: { saved: true } };
  });
  const { Provider, useMcpApp } = await import("./host");
  function Probe() {
    const { data, viewState, setViewState } = useMcpApp<{title:string}>();
    return <><span>{data?.title}</span><span>page:{String(viewState.page)}</span><button onClick={() => setViewState("page", 9)}>edit</button></>;
  }
  render(<Provider devMock={{title:"dev"}}><Probe /></Provider>);
  await act(async () => {});
  const publish = (title: string, capability: string) => window.dispatchEvent(new CustomEvent("openai:set_globals", { detail: { globals: { toolOutput: { title }, toolResponseMetadata: { mcp_tool_result: { _meta: { "lobu/mcp-app-snapshot-capability": capability } } } } } }));
  act(() => publish("First", "first-cap"));
  await screen.findByText("page:1");
  fireEvent.click(screen.getByText("edit"));
  expect(screen.getByText("page:9")).toBeInTheDocument();
  act(() => publish("Second", "second-cap"));
  await screen.findByText("Second");
  await waitFor(() => expect(screen.getByText("page:2")).toBeInTheDocument());
});
EOF
